import{C as e,u as t}from"./console-core-DwKGUhcn.js";import{x as n}from"./console-icons-Gzwi7pQZ.js";var r=t(`beaker`,[[`path`,{d:`M4.5 3h15`,key:`c7n0jr`}],[`path`,{d:`M6 3v16a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2V3`,key:`m1uhx7`}],[`path`,{d:`M6 14h12`,key:`4cwo0f`}]]),i=t(`compass`,[[`circle`,{cx:`12`,cy:`12`,r:`10`,key:`1mglay`}],[`path`,{d:`m16.24 7.76-1.804 5.411a2 2 0 0 1-1.265 1.265L7.76 16.24l1.804-5.411a2 2 0 0 1 1.265-1.265z`,key:`9ktpf1`}]]),a=t(`shield-alert`,[[`path`,{d:`M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z`,key:`oel41y`}],[`path`,{d:`M12 8v4`,key:`1got3b`}],[`path`,{d:`M12 16h.01`,key:`1drbdi`}]]),o=e(),s=[{state:`Available in this build`,slug:`available`,icon:n,items:[[`Workbench + themes`,`Local workbench, paired themes, and recent bounded discoveries.`],[`gRPC workbench`,`Reflection, proto/protoset schemas, all stream modes, deadlines, headers, messages, trailers, and status.`],[`HTTP workbench`,`Bounded HTTP(S), verified TLS, explicit redirects, peer, timing, headers, response bodies, and bounded credential-redacted cURL export.`],[`Bounded discovery`,`Explicit TCP, gRPC, TLS, and HTTP evidence with fixed candidate and time limits.`],[`Next-hop evidence`,`One read-only kernel route lookup per resolved address from the ProtoPeek process; no hop probes.`],[`Network Path · Linux`,`Built-in unprivileged UDP error-queue probes with one pinned destination, separate DNS and kernel-route evidence, silent hops, ECMP responders, and source-to-responder RTT.`],[`Authorized private discovery`,`Explicit RFC 1918 IPv4 /24-or-smaller discovery with a previewed plan: bounded gRPC/HTTP inspection only on named application ports, TCP connect-only evidence elsewhere, hard limits, and cancellation.`],[`Network map + history`,`Responsive topology and accessible inventory views, manual subnet/site/VLAN/region groups, immutable snapshots, tags and notes, bounded browser persistence, and JSON/GraphML/CSV exchange.`],[`Offline Nmap XML import`,`Bounded hints from an existing nmap -oX file. Nmap is not required for import; literal-IP endpoints are verified before opening a workbench.`],[`Browser proto folders`,`Review and upload a bounded relative-path .proto manifest to the running ProtoPeek instance; folder access and schema bytes are never saved in profiles.`],[`gRPC Health Check + Watch`,`Explicit canonical checks and one bounded live Watch with status transitions, headers, trailers, cancellation, and final gRPC evidence; no polling or retry.`],[`Downloader`,`One to 32 independent HTTP(S) jobs through configured or system aria2c, with bounded per-job options, queue controls, private retry state, checksum evidence, and one-shot CLI transfer.`],[`Security evidence`,`One disclosed historical certificate-name lookup and one separately consented public-only HEAD observation, plus a deterministic local observed/not observed/attention report from that retained response; no added target request or security score.`],[`GoBarryGo bridge`,`Read-first preview, bounded copy-only preference/session import, paused imported jobs, private receipts, and guarded rollback without changing GoBarryGo source files.`],[`Cloudflare Tunnels · local foundation`,`Manual, read-only discovery of cloudflared, its canonical OS service, documented config candidates, config authority, ingress routes, and Docker and Wrangler availability, plus safe in-view route drafts.`],[`Owned package channels`,`Homebrew on macOS/Linux and Scoop on Windows install checksum-pinned v0.5.0 archives, declare aria2 as an external dependency, and provide both protopeek and pp.`]]},{state:`Next`,slug:`next`,icon:i,items:[[`Incremental response-lab streams`,`Render each general server-stream message immediately with bounded retention while keeping headers, trailers, cancellation, and final status distinct.`],[`Saved HTTP requests + profiles`,`Reusable local request recipes and environment values with secret-safe persistence.`],[`cURL import`,`Parse a deliberately bounded cURL subset without silently accepting unsafe shell behavior; export is available now.`],[`Target DNS + TLS preflight`,`Explain resolution, SNI, ALPN, certificate verification, and handshake timing before an RPC or HTTP request.`],[`Darwin + Windows path backends`,`Earn native unprivileged implementations with equivalent cancellation and evidence semantics; no localized subprocess parsing or elevation prompts.`],[`Snapshot diff + sourced enrichment`,`Compare immutable observations and attach attributed, user-supplied region/ASN evidence without pretending an IP address proves a datacenter.`],[`WinGet package`,`Prepare and owner-submit a schema-valid Windows package only after the owned Scoop path and installer have initial user feedback.`],[`Tunnel validation + runtime evidence`,`Add authoritative cloudflared validation, route matching, bounded logs, metrics, and diagnostics without ambient polling or credential reads.`]]},{state:`Exploring`,slug:`exploring`,icon:r,items:[[`WebSocket + SSE`,`Protocol-native event timelines, cancellation, and bounded payload retention.`],[`Bounded PCAP import`,`Offline evidence with an explicit Wireshark/TShark handoff; no hidden capture.`],[`Nmap XML to topology`,`Map bounded existing XML hints into a saved workspace with import provenance and explicit loss notices, without executing Nmap.`],[`Cap'n Proto`,`A schema/capability inspector only if native evidence and dependency size earn a surface.`],[`QUIC + HTTP/3`,`Negotiation and transport evidence once a compact, reliable cross-platform path is proven.`]]},{state:`Gated`,slug:`gated`,icon:a,items:[[`Bundled Nmap execution`,`Not planned for the core binary. Reconsider only as an opt-in companion with explicit executable choice, previewed scope, hard budgets, and an auditable command.`],[`Broader/public range discovery`,`Why: one authorized private /24 must not become ambient or Internet-wide crawling. Gate: a distinct workflow, previewed scope, harder budgets, and a defensible user need.`],[`Automatic datacenter geolocation claims`,`Why: SIN, BOM, provider-region labels, WHOIS, and IP geolocation are hints rather than measured facilities. Gate: user-supplied sources, attribution, freshness, and confidence.`],[`Live capture`,`Why: capture can require privilege and expose payload secrets. Gate: explicit lifecycle, redaction/export policy, and dependable cross-platform teardown.`],[`Tunnel service and config mutation`,`Why: host service control, credential paths, and config writes cross a privilege boundary. Gate: deliberate elevation, least-privilege helpers, atomic writes, validation, rollback, and auditable receipts.`]]}];function c(){return(0,o.jsxs)(`div`,{className:`pp-evidence-workbench pp-roadmap-page`,children:[(0,o.jsx)(`header`,{className:`pp-evidence-hero`,children:(0,o.jsxs)(`div`,{children:[(0,o.jsx)(`span`,{className:`pp-kicker`,children:`Capability contract`}),(0,o.jsx)(`h1`,{children:`Product roadmap`}),(0,o.jsx)(`p`,{children:`What works now, what closes daily workflow gaps next, and what needs a safety gate.`})]})}),(0,o.jsx)(`div`,{className:`pp-roadmap-grid`,children:s.map(e=>(0,o.jsxs)(`section`,{className:`pp-roadmap-group is-${e.slug}`,children:[(0,o.jsxs)(`header`,{children:[(0,o.jsx)(e.icon,{"aria-hidden":`true`}),(0,o.jsx)(`h2`,{children:e.state}),(0,o.jsx)(`span`,{children:e.items.length})]}),(0,o.jsx)(`div`,{children:e.items.map(([e,t])=>(0,o.jsxs)(`article`,{children:[(0,o.jsx)(`h3`,{children:e}),(0,o.jsx)(`p`,{children:t})]},e))})]},e.state))})]})}export{c as Roadmap};